### Step 4: Implement the CSV service

In the `csv` service, we will use a web worker to download the CSV file in the background.

```javascript
// services/csv.js
import { Worker } from 'worker_threads';
import { inject as service } from '@ember/service';

export default class CSVService {
  @service store;

  async downloadCSV(csvData) {
    const worker = new Worker('./workers/download-csv.js', {
      workerData: csvData,
    });

    return new Promise((resolve, reject) => {
      worker.on('message', (data) => {
        resolve(data);
      });

      worker.on('error', (error) => {
        reject(error);
      });
    });
  }
}
```

### Step 5: Implement the web worker

In the `download-csv.js` file, we will implement the logic for downloading the CSV file.

```javascript
// workers/download-csv.js
import { parentPort } from 'worker_threads';

parentPort.on('message', (csvData) => {
  const csvString = csvData.join('\n');
  const blob = new Blob([csvString], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'data.csv';
  a.click();
  URL.revokeObjectURL(url);
  parentPort.postMessage('Download complete');
});
```

